"""Emitters: turn a parsed calibration schema into C, Python, JSON and Markdown.

Deterministic by construction: no timestamps, no dict-order dependence, no absolute
paths.  Running the generator twice on the same schema produces byte-identical files,
which is what makes the CI regeneration diff a meaningful gate.
"""

from __future__ import annotations

import json
from typing import Any

from rc_schema import (
    SCALAR_TYPES,
    INTEGER_TYPES,
    SOURCES as SOURCES_DOC,
    Item,
    SCALAR_TYPES,
    Schema,
    fmt_number,
)

BANNER = (
    "/* Generated by tools/codegen/generate.py from the schema under configs/schema.\n"
    " * DO NOT EDIT - edit the schema YAML and regenerate.\n"
    " */\n"
)

C_KEYWORDS = {
    "auto", "break", "case", "char", "const", "continue", "default", "do", "double",
    "else", "enum", "extern", "float", "for", "goto", "if", "inline", "int", "long",
    "register", "restrict", "return", "short", "signed", "sizeof", "static", "struct",
    "switch", "typedef", "union", "unsigned", "void", "volatile", "while", "bool",
    "true", "false", "class", "new", "delete", "this", "operator", "template",
}


SCALAR_C_TYPES = {"f32": "float", "f64": "double", "u8": "uint8_t",
                 "u16": "uint16_t", "u32": "uint32_t", "i8": "int8_t",
                 "i16": "int16_t", "i32": "int32_t"}


def cf(value: Any) -> str:
    """Format a Python number as a C float literal (always with a decimal point)."""
    text = fmt_number(value)
    if "." in text or "e" in text or "inf" in text or "nan" in text:
        return text
    return text + ".0"


def c_ident(name: str) -> str:
    out = "".join(ch if ch.isalnum() else "_" for ch in name)
    if out and out[0].isdigit():
        out = "_" + out
    if out in C_KEYWORDS:
        out += "_"
    return out


def field_name(item: Item) -> str:
    return c_ident(f"{item.group}_{item.name}")


def id_enum(item: Item) -> str:
    return "RC_CAL_ID_" + c_ident(f"{item.group}_{item.name}").upper()


def py_name(name: str) -> str:
    return name.replace(".", "_")


def table_array(item: Item) -> str:
    return f"{field_name(item)}_cells"


# --------------------------------------------------------------------------- C


def emit_c_header(schema: Schema) -> str:
    out: list[str] = [
        BANNER,
        "#pragma once",
        "",
        "#include <stdbool.h>",
        "#include <stddef.h>",
        "#include <stdint.h>",
        "",
        "typedef struct rc_cal rc_cal_t;",
        "",
    ]
    out.append(f"#define RC_CAL_SCHEMA_VERSION {schema.version}")
    out.append(f"#define RC_CAL_IMAGE_SIZE {schema.total_size}u")
    out.append("")
    out.append("/* ---------------------------------------------------------------- ids */")
    out.append("typedef enum {")
    for name in schema.order:
        item = schema.items[name]
        out.append(f"    {id_enum(item)} = 0x{item.id:04X},")
    out.append("    RC_CAL_ID__COUNT = 0xFFFF")
    out.append("} rc_cal_id_t;")
    out.append("")

    out.append("/* --------------------------------------------------------- descriptors */")
    out.append("typedef enum {")
    out.append("    RC_CAL_T_BOOL = 0, RC_CAL_T_U8, RC_CAL_T_I8, RC_CAL_T_U16,")
    out.append("    RC_CAL_T_I16, RC_CAL_T_U32, RC_CAL_T_I32, RC_CAL_T_F32,")
    out.append("    RC_CAL_T_ENUM, RC_CAL_T_BITS, RC_CAL_T_TABLE2D, RC_CAL_T_AXIS1D")
    out.append("} rc_cal_type_t;")
    out.append("")
    out.append("typedef enum {")
    out.append("    RC_CAL_OWNER_READ_ONLY = 0, RC_CAL_OWNER_ENGINEER,")
    out.append("    RC_CAL_OWNER_TUNER, RC_CAL_OWNER_SAFETY, RC_CAL_OWNER_MODE")
    out.append("} rc_cal_owner_t;")
    out.append("")
    out.append("typedef enum {")
    out.append("    RC_CAL_SAFETY_INFORMATIONAL = 0, RC_CAL_SAFETY_MEDIUM,")
    out.append("    RC_CAL_SAFETY_HIGH, RC_CAL_SAFETY_CRITICAL")
    out.append("} rc_cal_safety_t;")
    out.append("")
    out.append("/* Provenance of the shipped default. See docs/CALIBRATION_SPEC.md. */")
    out.append("typedef enum {")
    for i, src in enumerate(
        (
            "SOURCE_DERIVED", "CALCULATED", "MEASURED", "SIMULATED", "HIL_VERIFIED",
            "BENCH_MEASURED", "ENGINE_TESTED", "DYNO_MEASURED", "VEHICLE_VALIDATED",
            "UNVERIFIED",
        )
    ):
        out.append(f"    RC_CAL_SRC_{src} = {i},")
    out.append("} rc_cal_source_t;")
    out.append("")
    out.append("typedef struct {")
    out.append("    uint16_t    id;")
    out.append("    uint16_t    offset;")
    out.append("    uint16_t    size;")
    out.append("    uint8_t     type;")
    out.append("    uint8_t     owner;")
    out.append("    uint8_t     safety;")
    out.append("    uint8_t     default_source;")
    out.append("    float       scale;")
    out.append("    float       minimum;")
    out.append("    float       maximum;")
    out.append("    const char* group;")
    out.append("    const char* name;")
    out.append("    const char* unit;")
    out.append("    uint8_t     alloc_rows;")
    out.append("    uint8_t     alloc_cols;")
    out.append("    uint8_t     cell_bytes;  /* stored width of one table cell or axis breakpoint */")
    out.append("} rc_cal_desc_t;")
    out.append("")
    out.append("extern const rc_cal_desc_t rc_cal_desc[];")
    out.append("extern const uint16_t rc_cal_desc_count;")
    out.append("extern const rc_cal_t rc_cal_defaults;")
    out.append("")
    out.append("/* ------------------------------------------------------------- the image */")
    out.append("struct rc_cal {")
    for name in schema.order:
        item = schema.items[name]
        if item.is_table:
            ctype = item.c_type()
            out.append(
                f"    {ctype} {table_array(item)}[{item.alloc_rows * item.alloc_cols}];"
                f"  /* {item.name} {item.alloc_rows}x{item.alloc_cols} */"
            )
        elif item.is_axis:
            out.append(
                f"    {item.c_type()} {table_array(item)}[{item.alloc_count}];"
                f"  /* {item.name}: {item.alloc_count} axis breakpoints */"
            )
        else:
            out.append(f"    {item.c_type()} {field_name(item)};  /* {item.name} */")
    out.append("};")
    out.append("")
    out.append("/* Compile-time proof that the generated layout matches the schema. */")
    for name in schema.order:
        item = schema.items[name]
        member = table_array(item) if (item.is_table or item.is_axis) else field_name(item)
        out.append(f'_Static_assert(offsetof(rc_cal_t, {member}) == {item.offset}u, "{item.name} offset");')
    out.append(f'_Static_assert(sizeof(rc_cal_t) <= RC_CAL_IMAGE_SIZE, "image size");')
    out.append("")
    return "\n".join(out) + "\n"


def emit_c_defaults(schema: Schema) -> str:
    out: list[str] = [BANNER, '#include "cal_types.h"', ""]
    out.append("/* Shipped defaults expressed as macros, so the assertions below are real")
    out.append(" * compile-time proofs about the values that are actually initialised. */")
    for name in schema.order:
        item = schema.items[name]
        if item.is_table or item.is_axis:
            continue
        macro = "RC_DEF_" + c_ident(f"{item.group}_{item.name}").upper()
        # f32 items need a float literal: a bare double would warn under -Wconversion.
        literal = cf(item.raw_default) + "f" if item.is_float else fmt_number(item.raw_default)
        out.append(f"#define {macro} {literal}")
    out.append("")
    out.append("const rc_cal_t rc_cal_defaults = {")
    for name in schema.order:
        item = schema.items[name]
        if item.is_table or item.is_axis:
            continue
        macro = "RC_DEF_" + c_ident(f"{item.group}_{item.name}").upper()
        literal = cf(item.raw_default) + "f" if item.is_float else fmt_number(item.raw_default)
        out.append(f"    .{field_name(item)} = {macro},  /* {item.name} */")
    out.append("};")
    out.append("")
    out.append("/* Tables are initialised to their declared fill.  A zero-filled calibration")
    out.append(" * table is not conservative, it is broken: it commands no air, so no fuel. */")
    for name in schema.order:
        item = schema.items[name]
        if not item.is_table:
            continue
        cells = item.alloc_rows * item.alloc_cols
        macro = "RC_DEF_" + c_ident(f"{item.group}_{item.name}").upper() + "_FILL"
        if item.cell_type == "f32":
            # %.6g drops the decimal point for a whole number, which would emit "10f" and
            # fail to compile, so the point is restored when the format drops it.
            text = f"{item.default_fill:.6g}"
            if "." not in text and "e" not in text and "E" not in text and "inf" not in text:
                text += ".0"
            out.append(f"#define {macro} {text}f")
        else:
            out.append(f"#define {macro} {int(round(item.default_fill))}")
        out.append(
            f"static void rc_cal_fill_{c_ident(f'{item.group}_{item.name}').lower()}(rc_cal_t *image)"
        )
        out.append("{")
        out.append(f"    for (uint32_t i = 0u; i < {cells}u; ++i) {{")
        if item.cell_type == "f32":
            out.append(f"        image->{table_array(item)}[i] = {macro};")
        else:
            out.append(f"        image->{table_array(item)}[i] = {macro};")
        out.append("    }")
        out.append("}")
        out.append("")
    out.append("void rc_cal_apply_table_fills(rc_cal_t *image);")
    out.append("")
    for name in schema.order:
        item = schema.items[name]
        if item.is_table:
            out.append(f"static void rc_cal_fill_{c_ident(f'{item.group}_{item.name}').lower()}(rc_cal_t *image);")
    out.append("")
    out.append("void rc_cal_apply_table_fills(rc_cal_t *image)")
    out.append("{")
    for name in schema.order:
        item = schema.items[name]
        if item.is_table:
            out.append(f"    rc_cal_fill_{c_ident(f'{item.group}_{item.name}').lower()}(image);")
    out.append("}")
    out.append("")
    out.append("/* Axes are laid out evenly across their declared range.  An evenly spaced axis is")
    out.append(" * the correct STARTING point and no more: the whole reason the breakpoints are")
    out.append(" * in the calibration is that a tuner moves them to put the resolution where the")
    out.append(" * engine actually spends its time.  A hard-coded axis would put that decision in")
    out.append(" * the firmware, where nobody tunes it. */")
    for name in schema.order:
        item = schema.items[name]
        if not item.is_axis:
            continue
        out.append(f"static void rc_cal_axis_{c_ident(f'{item.group}_{item.name}').lower()}(rc_cal_t *image)")
        out.append("{")
        for index, value in enumerate(item.default_points()):
            out.append(f"    image->{table_array(item)}[{index}] = {value:g};")
        out.append("}")
        out.append("")
    out.append("void rc_cal_apply_axis_defaults(rc_cal_t *image);")
    out.append("")
    for name in schema.order:
        item = schema.items[name]
        if item.is_axis:
            out.append(f"static void rc_cal_axis_{c_ident(f'{item.group}_{item.name}').lower()}(rc_cal_t *image);")
    out.append("")
    out.append("void rc_cal_apply_axis_defaults(rc_cal_t *image)")
    out.append("{")
    for name in schema.order:
        item = schema.items[name]
        if item.is_axis:
            out.append(f"    rc_cal_axis_{c_ident(f'{item.group}_{item.name}').lower()}(image);")
    out.append("}")
    out.append("")
    out.append("/* Integer-typed defaults: compile-time proof that each sits inside its own")
    out.append(" * declared bounds, so a schema mistake can never reach the firmware.")
    out.append(" * Float-typed defaults are checked at runtime by rc_cal_check_bounds()")
    out.append(" * because _Static_assert cannot consume a floating constant. */")
    for name in schema.order:
        item = schema.items[name]
        if (item.is_table or item.is_axis or item.is_enum or item.is_bits
                or item.is_float):
            continue
        macro = "RC_DEF_" + c_ident(f"{item.group}_{item.name}").upper()
        out.append(
            f'_Static_assert({macro} >= {fmt_number(item.raw_minimum)} && '
            f'{macro} <= {fmt_number(item.raw_maximum)}, "{item.name} default within bounds");'
        )
    out.append("")
    return "\n".join(out) + "\n"


def emit_c_descriptors(schema: Schema) -> str:
    out: list[str] = [BANNER, '#include "cal_types.h"', ""]
    out.append("const rc_cal_desc_t rc_cal_desc[] = {")
    for name in schema.order:
        item = schema.items[name]
        ctype = {"bool": "RC_CAL_T_BOOL"}.get(item.type, f"RC_CAL_T_{item.type.upper()}")
        if item.type == "enum":
            ctype = "RC_CAL_T_ENUM"
        if item.type == "bits":
            ctype = "RC_CAL_T_BITS"
        if item.is_table:
            ctype = "RC_CAL_T_TABLE2D"
        if item.is_axis:
            ctype = "RC_CAL_T_AXIS1D"
        out.append(
            "    {{ 0x{item.id:04X}, {off}, {size}, {ctype}, RC_CAL_OWNER_{owner}, "
            "RC_CAL_SAFETY_{safety}, RC_CAL_SRC_{src}, {scale}f, {lo}f, {hi}f, "
            '"{group}", "{name}", "{unit}", {ar}, {ac}, {cw} }},'.format(
                item=item,
                off=item.offset,
                size=item.storage_units(),
                ctype=ctype,
                owner=item.owner,
                safety=item.safety_class,
                src=item.default_source.replace("-", "_"),
                scale=cf(item.scale),
                lo=cf(item.minimum),
                hi=cf(item.maximum),
                group=item.group,
                name=item.name,
                unit=item.unit,
                ar=item.alloc_rows,
                ac=item.alloc_cols,
                cw=_item_bytes(item) if (item.is_table or item.is_axis) else 0,
            )
        )
    out.append("};")
    out.append("")
    out.append("const uint16_t rc_cal_desc_count = (uint16_t)(sizeof(rc_cal_desc) / sizeof(rc_cal_desc[0]));")
    out.append("")
    return "\n".join(out) + "\n"


def emit_c_access(schema: Schema) -> str:
    out: list[str] = [BANNER, "#pragma once", "", '#include "cal_types.h"', ""]
    out.append("/* Inline accessors in ENGINEERING units. The raw image is never touched")
    out.append(" * by control code directly: this is what keeps scale/offset bugs out of the")
    out.append(" * engine core.")
    out.append(" *")
    out.append(" * Every WRITE goes through the matching setter, which applies the scale and")
    out.append(" * refuses a value outside the item's own range.  That matters: an item stored")
    out.append(" * at 0.01 deg resolution holds 275.0 deg as 27500, so writing an engineering")
    out.append(" * value straight into the raw field silently commands 2.75 deg.  A rejected")
    out.append(" * write is always better than a plausible-looking wrong one. */")
    for name in schema.order:
        item = schema.items[name]
        if item.is_axis:
            fn = py_name(f"{item.group}_{item.name}")
            out.append(
                f"static inline float rc_cal_get_{fn}(const rc_cal_t* c, uint8_t index)"
            )
            out.append("{")
            out.append(f"    return (float)c->{table_array(item)}[index] * {cf(item.scale)}f;")
            out.append("}")
            out.append("")
            continue
        if item.is_table:
            out.append(
                f"static inline float rc_cal_get_{py_name(f"{item.group}_{item.name}")}(const rc_cal_t* c,"
                f" uint8_t row, uint8_t col)"
            )
            out.append("{")
            out.append(
                f"    return (float)c->{table_array(item)}[(size_t)row * {item.alloc_cols}u + col] * {cf(item.scale)}f;"
            )
            out.append("}")
            out.append("")
            continue
        if item.type == "enum":
            out.append(f"static inline uint8_t rc_cal_get_{py_name(f"{item.group}_{item.name}")}(const rc_cal_t* c)")
            out.append("{")
            out.append(f"    return c->{field_name(item)};")
            out.append("}")
            out.append("")
            continue
        if item.type == "bits":
            out.append(f"static inline uint16_t rc_cal_get_{py_name(f"{item.group}_{item.name}")}(const rc_cal_t* c)")
            out.append("{")
            out.append(f"    return c->{field_name(item)};")
            out.append("}")
            out.append("")
            continue
        ctype = item.c_type()
        if item.type == "bool":
            out.append(f"static inline bool rc_cal_get_{py_name(f"{item.group}_{item.name}")}(const rc_cal_t* c)")
            out.append("{")
            out.append(f"    return c->{field_name(item)} != 0;")
            out.append("}")
            out.append("")
            continue
        scale = cf(item.scale)
        if item.scale == 1.0:
            out.append(f"static inline {ctype} rc_cal_get_{py_name(f"{item.group}_{item.name}")}(const rc_cal_t* c)")
            out.append("{")
            out.append(f"    return c->{field_name(item)};")
            out.append("}")
        else:
            out.append(f"static inline float rc_cal_get_{py_name(f"{item.group}_{item.name}")}(const rc_cal_t* c)")
            out.append("{")
            out.append(f"    return (float)c->{field_name(item)} * {scale}f;")
            out.append("}")
        out.append("")
    out.append("/* ------------------------------------------------------------ setters */")
    out.append("")
    for name in schema.order:
        item = schema.items[name]
        fn = py_name(f"{item.group}_{item.name}")
        if item.is_axis:
            out.append(
                f"static inline bool rc_cal_set_{fn}(rc_cal_t* c, uint8_t index, float value)"
            )
            out.append("{")
            out.append(f"    if (index >= {item.alloc_count}u) {{")
            out.append("        return false;")
            out.append("    }")
            out.append(
                f"    if (!(value >= {cf(item.minimum)}f) || !(value <= {cf(item.maximum)}f)) {{"
            )
            out.append("        return false;")
            out.append("    }")
            out.append(
                f"    c->{table_array(item)}[index] = ({item.c_type()})(value / {cf(item.scale)}f);"
            )
            out.append("    return true;")
            out.append("}")
            out.append("")
            continue
        if item.is_table:
            out.append(
                f"static inline bool rc_cal_set_{fn}(rc_cal_t* c, uint8_t row, uint8_t col, float value)"
            )
            out.append("{")
            out.append(
                f"    if ((float)row >= {item.alloc_rows}u || (float)col >= {item.alloc_cols}u) {{"
            )
            out.append("        return false;")
            out.append("    }")
            cell_lo, cell_hi = SCALAR_TYPES[item.cell_type][2:]
            if not (cell_lo >= item.cell_min and cell_hi <= item.cell_max):
                out.append(
                    f"    if (!(value >= {cf(item.cell_min)}f) || !(value <= {cf(item.cell_max)}f)) {{"
                )
                out.append("        return false;")
                out.append("    }")
            out.append(
                f"    c->{table_array(item)}[(size_t)row * {item.alloc_cols}u + col] = "
                f"({SCALAR_C_TYPES[item.cell_type]})(value / {cf(item.scale)}f);"
            )
            out.append("    return true;")
            out.append("}")
            out.append("")
            continue
        if item.type == "enum":
            out.append(f"static inline bool rc_cal_set_{fn}(rc_cal_t* c, uint8_t value)")
            out.append("{")
            enum_hi = max((v.value for v in item.values), default=0)
            if enum_hi < 255:
                out.append(f"    if (value > {enum_hi}u) {{")
                out.append("        return false;")
                out.append("    }")
            out.append(f"    c->{field_name(item)} = value;")
            out.append("    return true;")
            out.append("}")
            out.append("")
            continue
        if item.type == "bits":
            out.append(f"static inline bool rc_cal_set_{fn}(rc_cal_t* c, uint16_t value)")
            out.append("{")
            # A bitfield that fills its whole storage type has nothing left to reject.
            bits_hi = (1 << len(item.bits)) - 1
            if bits_hi < 0xFFFF:
                out.append(f"    if (value > {bits_hi}u) {{")
                out.append("        return false;")
                out.append("    }")
            out.append(f"    c->{field_name(item)} = ({item.c_type()})value;")
            out.append("    return true;")
            out.append("}")
            out.append("")
            continue
        ctype = item.c_type()
        if item.type == "bool":
            out.append(f"static inline bool rc_cal_set_{fn}(rc_cal_t* c, bool value)")
            out.append("{")
            out.append(f"    c->{field_name(item)} = value ? 1u : 0u;")
            out.append("    return true;")
            out.append("}")
            out.append("")
            continue
        out.append(f"static inline bool rc_cal_set_{fn}(rc_cal_t* c, float value)")
        out.append("{")
        # An item whose range already spans its whole storage type cannot be range-checked
        # without a tautology the compiler rightly rejects; only emit the check when it
        # can actually reject something.
        # The check is only a tautology when the item's own range is at least as wide as
        # the storage type, because then every representable value is already legal.
        raw_min, raw_max = SCALAR_TYPES[item.type][2:]
        checkable = not (raw_min >= item.raw_minimum and raw_max <= item.raw_maximum)
        if checkable:
            out.append(
                f"    if (!(value >= {cf(item.minimum)}f) || !(value <= {cf(item.maximum)}f)) {{"
            )
            out.append("        return false;")
            out.append("    }")
        out.append(f"    c->{field_name(item)} = ({ctype})(value / {cf(item.scale)}f);")
        out.append("    return true;")
        out.append("}")
        out.append("")
    return "\n".join(out) + "\n"


# ---------------------------------------------------------------------- Python


def emit_python(schema: Schema) -> str:
    out: list[str] = [
        '"""Generated from configs/schema/*.yaml. DO NOT EDIT.',
        "",
        "Holds the calibration id constants, enum types, descriptor table and the",
        "shipped defaults, all in engineering units.  The behaviour lives in",
        "tuner/calibration/; this module is data only.",
        '"""',
        "",
        "from __future__ import annotations",
        "",
        "from dataclasses import dataclass",
        "from enum import IntEnum",
        "",
        f"SCHEMA_VERSION = {schema.version}",
        f"IMAGE_SIZE = {schema.total_size}",
        "",
    ]
    for group in schema.groups:
        items = [schema.items[n] for n in schema.order if schema.items[n].group == group]
        if not any(i.type == "enum" for i in items):
            continue
        out.append(f"class {c_ident(group).capitalize()}(IntEnum):")
        for item in items:
            if item.type != "enum":
                continue
            out.append(f'    """{item.description or item.name}"""')
            out.append("")
            for v in item.values:
                member = c_ident(f"{item.name}_{v.name}").upper()
                out.append(f"    {member} = {v.value}")
            out.append("")
        out.append("")

    out.append("@dataclass(frozen=True)")
    out.append("class Descriptor:")
    out.append('    """One calibration item, as consumed by the tuner."""')
    out.append("")
    out.append("    name: str")
    out.append("    id: int")
    out.append("    offset: int")
    out.append("    size: int")
    out.append("    type: str")
    out.append("    unit: str")
    out.append("    scale: float")
    out.append("    minimum: float")
    out.append("    maximum: float")
    out.append("    owner: str")
    out.append("    safety_class: str")
    out.append("    default_source: str")
    out.append("    description: str")
    out.append("    alloc_rows: int = 0")
    out.append("    alloc_cols: int = 0")
    out.append("")
    out.append("    @property")
    out.append("    def is_table(self) -> bool:")
    out.append('        return self.type == "table2d"')
    out.append("")
    out.append("    @property")
    out.append("    def editable(self) -> bool:")
    out.append('        """A READ_ONLY item is derived; the GUI must not offer it for edit."""')
    out.append('        return self.owner != "READ_ONLY"')
    out.append("")

    out.append("DESCRIPTORS: tuple[Descriptor, ...] = (")
    for name in schema.order:
        item = schema.items[name]
        lo = item.minimum if item.minimum is not None else 0
        hi = item.maximum if item.maximum is not None else 0
        desc = item.description.replace('"', "'")
        out.append("    Descriptor(")
        out.append(f'        name="{item.name}",')
        out.append(f"        id=0x{item.id:04X},")
        out.append(f"        offset={item.offset},")
        out.append(f"        size={item.storage_units()},")
        out.append(f'        type="{item.type}",')
        out.append(f'        unit="{item.unit}",')
        out.append(f"        scale={item.scale},")
        out.append(f"        minimum={float(lo)!r},")
        out.append(f"        maximum={float(hi)!r},")
        out.append(f'        owner="{item.owner}",')
        out.append(f'        safety_class="{item.safety_class}",')
        out.append(f'        default_source="{item.default_source}",')
        out.append(f'        description="{desc}",')
        if item.is_table:
            out.append(f"        alloc_rows={item.alloc_rows},")
            out.append(f"        alloc_cols={item.alloc_cols},")
        out.append("    ),")
    out.append(")")
    out.append("")
    out.append("BY_NAME = {d.name: d for d in DESCRIPTORS}")
    out.append("BY_ID = {d.id: d for d in DESCRIPTORS}")
    out.append("")
    out.append("DEFAULTS = {")
    for name in schema.order:
        item = schema.items[name]
        if item.is_table:
            out.append(f'    "{item.name}": 0.0,  # {item.alloc_rows}x{item.alloc_cols} table, zero filled')
        elif item.is_enum or item.is_bits:
            out.append(f'    "{item.name}": {int(item.raw_default)},')
        else:
            out.append(f'    "{item.name}": {item.to_engineering(item.raw_default)!r},')
    out.append("}")
    out.append("")
    out.append("")
    out.append("def unverified_items() -> list[str]:")
    out.append('    """Items whose shipped default is an unmeasured placeholder.')
    out.append("")
    out.append("    The ECU raises an informational DTC when an unverified item is used")
    out.append("    outside bench/dyno mode, and the GUI badges them in the calibration")
    out.append("    browser.  See docs/CALIBRATION_SPEC.md 1.")
    out.append('    """')
    out.append("    return [d.name for d in DESCRIPTORS if d.default_source == \"UNVERIFIED\"]")
    out.append("")
    return "\n".join(out) + "\n"


# ------------------------------------------------------------------ JSON/docs


def _axes_of(schema: Schema, table: Item) -> list[Item]:
    """The axis1d items belonging to `table`, in schema order.

    Declared row-then-col in the schema, and that order is the link: there is no field in
    a 2-D item saying "this is my column axis", only the axis KIND on each side, and
    "rpm" names a dimension rather than an item.
    """
    return [
        item for item in (schema.items[n] for n in schema.order)
        if item.is_axis
        and item.group == table.group
        and item.name.startswith(table.name + "_")
        and item.name.endswith("_axis")
    ]


def _axis_for(schema: Schema, table: Item, side: str, kind: str) -> Item | None:
    """The axis1d item holding `table`'s breakpoints along one dimension.

    Matching on the axis kind first, because that is the declared relationship; falling
    back to declaration order, because a kind that does not match a name is still better
    matched to the right SIDE than to nothing. Returning None rather than a wrong item is
    deliberate: a host given a null can fall back visibly, and a host handed the wrong axis
    will not notice.
    """
    axes = _axes_of(schema, table)
    for item in axes:
        if item.name[len(table.name) + 1:-len("_axis")] == kind:
            return item
    if len(axes) >= 2:
        return axes[0] if side == "row" else axes[1]
    return axes[0] if axes else None


def _item_bytes(item: Any) -> int:
    """Width in bytes of one stored value (a table's is per cell)."""
    ctype = item.c_type()
    return {"float": 4, "double": 8, "uint8_t": 1, "int8_t": 1,
            "uint16_t": 2, "int16_t": 2, "uint32_t": 4, "int32_t": 4}.get(ctype, 1)


def descriptor_dict(schema: Schema) -> dict[str, Any]:
    items = []
    for name in schema.order:
        item = schema.items[name]
        lo, hi = item.cell_range()
        entry: dict[str, Any] = {
            "name": item.name,
            # The group travels with the item. A host cannot reconstruct it from the name,
            # and guessing produces a browser whose grouping disagrees with the schema -
            # which is confusing but, worse, makes a settings key that is not stable.
            "group": item.group,
            "id": f"0x{item.id:04X}",
            "offset": item.offset,
            "size": item.storage_units(),
            # The WIDTH IN BYTES, which `size` is not: size counts storage units, and one
            # unit of f32 is four bytes. A host that multiplies by four for floats and by
            # one for bytes can get this right, but only if it remembers; emitting the
            # number removes the opportunity to get it wrong.
            "bytes": item.byte_size() if hasattr(item, "byte_size") else _item_bytes(item),
            "type": item.type,
            "unit": item.unit,
            "scale": item.scale,
            "min": float(lo),
            "max": float(hi),
            "owner": item.owner,
            "safety_class": item.safety_class,
            "default_source": item.default_source,
            "source_ref": item.source_ref,
            "description": item.description,
            "live_edit": item.live_edit,
            "dependencies": item.dependencies,
        }
        # The default belongs in the descriptor, in ENGINEERING units. Without it a host
        # tool that wants to show "what the ECU ships with" has to guess, and guessing
        # produces a defaults screen that disagrees with the firmware - which is the thing
        # the operator is about to change.
        # A table's default is its FILL, not zero: that is the value every cell actually
        # ships with, and a host showing "0" would describe a calibration the ECU does not
        # have.
        entry["default"] = float(item.default_fill if (item.is_table or item.is_axis)
                                 else item.default)
        if item.type == "enum":
            entry["values"] = [{"name": v.name, "value": v.value} for v in item.values]
        if item.type == "bits":
            entry["bits"] = list(item.bits)
        if item.is_table:
            entry["alloc_rows"] = item.alloc_rows
            entry["alloc_cols"] = item.alloc_cols
            entry["cell_type"] = item.cell_type
            entry["row_axis"] = item.row_axis
            entry["col_axis"] = item.col_axis
            # row_axis above is the axis KIND ("rpm", "kPa"), which describes what the
            # dimension means but resolves to no item. These two carry the id of the actual
            # axis1d item holding the breakpoints, because a host that has to match on a
            # name convention will eventually match the wrong one.
            for side, kind in (("row", item.row_axis), ("col", item.col_axis)):
                axis = _axis_for(schema, item, side, kind)
                entry[f"{side}_axis_item"] = axis.name if axis else None
                entry[f"{side}_axis_id"] = f"0x{axis.id:04X}" if axis else None
        if item.is_axis:
            # The breakpoint count, the cell width, and the axis unit. A host needs the
            # count to index the array and the unit to label the axis, and without either
            # it has to guess - which is how a table ends up labelled "rpm" when it is MAP.
            entry["alloc_count"] = item.alloc_count
            entry["cell_type"] = item.cell_type
            entry["is_axis"] = True
            entry["axis"] = item.row_axis
        items.append(entry)
    # The cross-item rules travel in the descriptor too. The tuner's refusal dialog needs to
    # turn the index the ECU sent back into prose, and the only acceptable source for that
    # prose is the same rc_rules.RULES the firmware is generated from - a second hand-written
    # list would drift, and a drifted explanation of a safety rule is worse than none.
    from rc_rules import RULES

    rules = [
        {"index": index, "name": rule.name, "text": rule.text}
        for index, rule in enumerate(RULES)
    ]
    return {
        "schema_version": schema.version,
        "image_size": schema.total_size,
        "groups": schema.groups,
        "source_files": schema.source_files,
        "items": items,
        "rules": rules,
    }


def emit_c_rules(schema: Schema) -> str:
    """The cross-item rule list, generated from rc_rules.RULES.

    Generating it removes the possibility that the firmware and the build-time validator
    disagree about which rules exist; `tests/unit/test_calibration.c` checks the count and
    that every name is present, which is enough to catch an out-of-date checkout.
    """
    from rc_rules import RULES

    out: list[str] = [BANNER, "#pragma once", "", '#include "rc/rc_rules.h"', ""]
    out.append("/* Generated from tools/codegen/rc_rules.py. DO NOT EDIT. */")
    out.append(f"#define RC_GENERATED_RULE_COUNT {len(RULES)}u")
    out.append("")
    out.append("/* Stable index for each rule, so firmware code refers to a rule by a")
    out.append(" * generated constant rather than by a hand-kept ordinal. */")
    out.append("typedef enum {")
    for index, rule in enumerate(RULES):
        out.append(f"    RC_RULE_INDEX_{rule.name.upper()} = {index}u,")
    out.append(f"    RC_RULE_INDEX_COUNT = {len(RULES)}u")
    out.append("} rc_rule_index_t;")
    out.append("")
    out.append("static const char *const rc_rule_names[RC_GENERATED_RULE_COUNT] = {")
    for rule in RULES:
        out.append(f'    "{rule.name}",')
    out.append("};")
    out.append("")
    return "\n".join(out) + "\n"


def emit_json(schema: Schema) -> str:
    return json.dumps(descriptor_dict(schema), indent=2, sort_keys=False) + "\n"


def emit_docs(schema: Schema) -> str:
    out: list[str] = [
        "# Calibration Reference",
        "",
        "**Generated from `configs/schema/*.yaml`. DO NOT EDIT.**",
        "",
        f"Schema version {schema.version} - image size {schema.total_size} bytes - "
        f"{len(schema.order)} items.",
        "",
        "All values are in **engineering units**. Provenance tags: "
        + " / ".join(SOURCES_DOC),
        "",
    ]
    for group in schema.groups:
        items = schema.group_items(group)
        if not items:
            continue
        out.append(f"## `{group}`")
        out.append("")
        out.append("| ID | Name | Type | Unit | Default | Min | Max | Owner | Safety | Source |")
        out.append("|---|---|---|---|---|---|---|---|---|---|")
        for item in items:
            if item.is_table:
                ttype = f"table {item.alloc_rows}x{item.alloc_cols} {item.cell_type}"
                default, lo, hi = "0-filled", item.cell_min, item.cell_max
            elif item.is_enum:
                ttype = "enum"
                default, lo, hi = item.enum_name(int(item.raw_default)), 0, len(item.values) - 1
            elif item.is_bits:
                ttype = f"bits[{len(item.bits)}]"
                default, lo, hi = "0", 0, (1 << len(item.bits)) - 1
            else:
                ttype = item.type
                default = item.to_engineering(item.raw_default)
                lo, hi = item.cell_range()
            unit = f" {item.unit}" if item.unit else ""
            def fmt(v: object) -> str:
                if isinstance(v, str):
                    return v
                if isinstance(v, float):
                    return f"{v:.4g}"
                return str(v)
            out.append(
                f"| `0x{item.id:04X}` | `{item.name}` | {ttype} |{unit} | {fmt(default)} | "
                f"{fmt(lo)} | {fmt(hi)} | {item.owner} | {item.safety_class} | "
                f"{item.default_source}{(' ' + item.source_ref) if item.source_ref else ''} |"
            )
        out.append("")
        described = [i for i in items if i.description]
        if described:
            out.append("**Notes**")
            out.append("")
            for item in described:
                deps = (
                    f" Depends on: {', '.join(f'`{d}`' for d in item.dependencies)}."
                    if item.dependencies
                    else ""
                )
                out.append(f"- `{item.name}` - {item.description}{deps}")
            out.append("")
    return "\n".join(out) + "\n"
